CREATE TABLE sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(40) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,display_name VARCHAR(40) NOT NULL,role VARCHAR(20) NOT NULL,enabled BOOLEAN NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE tms_driver (id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(24) NOT NULL UNIQUE,name VARCHAR(40) NOT NULL,phone VARCHAR(20) NOT NULL,license_no VARCHAR(30) NOT NULL,license_expiry DATE NOT NULL,status VARCHAR(20) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE tms_vehicle (id BIGINT PRIMARY KEY AUTO_INCREMENT,plate_no VARCHAR(16) NOT NULL UNIQUE,vehicle_type VARCHAR(40) NOT NULL,capacity_tons DECIMAL(10,2) NOT NULL,capacity_cbm DECIMAL(10,2) NOT NULL,status VARCHAR(20) NOT NULL,current_position VARCHAR(80),created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE tms_transport_order (id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(32) NOT NULL UNIQUE,customer_name VARCHAR(80) NOT NULL,origin VARCHAR(120) NOT NULL,destination VARCHAR(120) NOT NULL,cargo_name VARCHAR(120) NOT NULL,weight_tons DECIMAL(10,2) NOT NULL,volume_cbm DECIMAL(10,2) NOT NULL,planned_pickup_at DATETIME NOT NULL,planned_delivery_at DATETIME NOT NULL,status VARCHAR(24) NOT NULL,priority VARCHAR(20) NOT NULL,driver_id BIGINT,vehicle_id BIGINT,freight_amount DECIMAL(12,2),proof_remark VARCHAR(200),created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_order_driver FOREIGN KEY(driver_id) REFERENCES tms_driver(id),CONSTRAINT fk_order_vehicle FOREIGN KEY(vehicle_id) REFERENCES tms_vehicle(id));
CREATE TABLE tms_tracking_event (id BIGINT PRIMARY KEY AUTO_INCREMENT,transport_order_id BIGINT NOT NULL,event_time DATETIME NOT NULL,location VARCHAR(80) NOT NULL,event_type VARCHAR(30) NOT NULL,description VARCHAR(240) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_tracking_order FOREIGN KEY(transport_order_id) REFERENCES tms_transport_order(id));
CREATE INDEX idx_tms_order_status ON tms_transport_order(status);CREATE INDEX idx_tms_order_pickup ON tms_transport_order(planned_pickup_at);CREATE INDEX idx_tracking_order_time ON tms_tracking_event(transport_order_id,event_time);
